<span class="line"><span style="color:#ABB2BF;">        tokens </span><span style="color:#56B6C2;">+=</span><span style="color:#ABB2BF;"> tokens_b </span><span style="color:#56B6C2;">+</span><span style="color:#ABB2BF;"> [</span><span style="color:#98C379;">&#39;&lt;sep&gt;&#39;</span><span style="color:#ABB2BF;">]</span></span>
